import Link from 'next/link'

export default function Forbidden() {
  return (
    <main
      style={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        minHeight: '100vh',
        fontFamily: 'system-ui, sans-serif',
        padding: '2rem',
        textAlign: 'center',
      }}
    >
      <h1
        style={{
          fontSize: '6rem',
          fontWeight: 'bold',
          color: '#dc2626',
          margin: '0',
          lineHeight: '1',
        }}
      >
        403
      </h1>
      <h2
        style={{
          fontSize: '1.5rem',
          fontWeight: '600',
          color: '#374151',
          marginTop: '1rem',
        }}
      >
        Access Forbidden
      </h2>
      <p
        style={{
          fontSize: '1rem',
          color: '#6b7280',
          marginTop: '0.5rem',
          maxWidth: '400px',
        }}
      >
        You don&apos;t have permission to access this page. Please contact an administrator if you believe this is an error.
      </p>
      <Link
        href="/"
        style={{
          marginTop: '2rem',
          padding: '0.75rem 1.5rem',
          backgroundColor: '#2563eb',
          color: 'white',
          borderRadius: '0.375rem',
          textDecoration: 'none',
          fontWeight: '500',
        }}
      >
        Go Home
      </Link>
    </main>
  )
}

